function script:qs_goal_done([string]$id) {
  switch -Exact ($id) {
    'look' {
      return [bool](q_used 'Get-ExecutionPolicy')
    }
    'run' {
      return [bool]((q_executable 'kettle-bot.ps1') -and (q_used 'Set-ExecutionPolicy'))
    }
    'power' {
      return [bool](q_treasure 'tea')
    }
    'path' {
      return [bool]((q_flag 'oiled') -and (q_env 'PATH' 'includes' 'tools'))
    }
    'tick' {
      return [bool]((q_function 'tick') -and (q_flag 'wound'))
    }
    'settings' {
      return [bool](q_variable 'GEAR_SIZE' '7')
    }
    'bell' {
      return [bool](q_flag 'rung')
    }
  }
  return $false
}

function script:qs_goal_teach([string]$id) {
  switch -Exact ($id) {
    'look' {
      q_say 'PowerShell won''t run script files until it''s told it may: that''s the execution policy. Get-ExecutionPolicy shows it. Restricted means no scripts at all.'
    }
    'run' {
      q_say 'Set-ExecutionPolicy -Scope CurrentUser RemoteSigned lets scripts you make run, and asks for downloaded ones to be signed. The kettle-bot was downloaded, so if you trust it, Unblock-File .\kettle-bot.ps1 removes the "from the internet" mark.'
    }
    'power' {
      q_say '$env:POWER = "on" sets an environment variable, which programs and scripts can read. (A plain $POWER = "on" would only be a PowerShell variable.) Then run .\kettle-bot.ps1.'
    }
    'path' {
      q_say '$env:PATH is the list of folders PowerShell searches when you type a command''s name, separated by semicolons. $env:PATH += ";$HOME\workshop\tools" adds the tools folder. Now oil works from anywhere.'
    }
    'tick' {
      q_say 'A PowerShell alias is only another name for one command, with no options, so use a function: function tick { .\clock.ps1 --wind --twice }. Then just type tick.'
    }
    'settings' {
      q_say 'Running .\settings.ps1 sets $GEAR_SIZE inside the script, and it''s gone when the script ends. A dot and a space in front, . .\settings.ps1 (dot-sourcing), runs it in YOUR session, so $GEAR_SIZE stays.'
    }
    'bell' {
      q_say 'Every command reports whether it worked: $? is True or False. && runs the next command only if the first one worked: .\gearbox.ps1 && .\bell.ps1.'
    }
  }
}

function script:qs_goal_hint([string]$id, [int]$level) {
  switch -Exact ("${id}:$level") {
    'look:1' {
      q_say 'Ask PowerShell what its script policy is.'
    }
    'look:2' {
      q_say 'Get-ExecutionPolicy'
    }
    'run:1' {
      q_say 'First allow scripts for yourself, then unblock the downloaded kettle-bot.'
    }
    'run:2' {
      q_say 'Set-ExecutionPolicy -Scope CurrentUser RemoteSigned, then Unblock-File .\kettle-bot.ps1'
    }
    'power:1' {
      q_say 'The kettle-bot reads POWER from the environment.'
    }
    'power:2' {
      q_say '$env:POWER = "on", then .\kettle-bot.ps1'
    }
    'path:1' {
      q_say 'Add the tools folder to the end of PATH, keeping what is already there.'
    }
    'path:2' {
      q_say '$env:PATH += ";$HOME\workshop\tools", then oil gears'
    }
    'tick:1' {
      q_say 'Make a short name that runs the clock with --wind --twice, then use it.'
    }
    'tick:2' {
      q_say 'function tick { .\clock.ps1 --wind --twice }, then tick'
    }
    'settings:1' {
      q_say 'Run the settings file in this shell, not a new one.'
    }
    'settings:2' {
      q_say '. .\settings.ps1'
    }
    'bell:1' {
      q_say 'Chain the two so the bell only rings after the gearbox works.'
    }
    'bell:2' {
      q_say '.\gearbox.ps1 && .\bell.ps1'
    }
  }
}

function script:qs_goal_solution([string]$id) {
  switch -Exact ($id) {
    'look' {
      return ,@('Get-ExecutionPolicy')
    }
    'run' {
      return ,@('Set-ExecutionPolicy -Scope CurrentUser RemoteSigned', 'Unblock-File .\kettle-bot.ps1')
    }
    'power' {
      return ,@('$env:POWER = "on"', '.\kettle-bot.ps1')
    }
    'path' {
      return ,@('$env:PATH += ";$HOME\workshop\tools"', 'oil gears')
    }
    'tick' {
      return ,@('function tick { .\clock.ps1 --wind --twice }', 'tick')
    }
    'settings' {
      return ,@('. .\settings.ps1')
    }
    'bell' {
      return ,@('.\gearbox.ps1 && .\bell.ps1')
    }
  }
}

function script:qs_finish_when {
  return [bool](q_flag 'rung')
}

function script:qs_finish_text {
  q_say 'Noon, right on time. Down in the town, people look up at the clock tower and smile. When Ada gets back, she''ll find tea, oiled gears, a wound clock and a bell that rings.

You gave programs permission to run, fed them settings through variables, taught the shell where to find them (PATH), gave a long command a short name, loaded settings into your own shell, and chained commands on whether they worked. That''s how real developer tools are set up and run.'
}

function script:qs_object([string]$obj, [string[]]$argv) {
  switch -Exact ($obj) {
    'kettle-bot' {
      if ((q_env 'POWER' 'equals' 'on')) {
        q_ran_mark 'kettle-bot'
        q_say 'The kettle-bot whirs, hisses, and pours you a perfect cup of tea.'
        q_flag_set 'tea'
        return 0
      }
      q_say 'NO POWER
      (The kettle-bot reads the environment variable $env:POWER. A plain $POWER is a PowerShell variable, which programs can''t see.)'
      return 1
    }
    'tools/oil' {
      if (($argv.Count -eq 1) -and ($argv[0] -eq 'gears')) {
        q_ran_mark 'tools/oil'
        q_say 'Glug, glug. The gears are oiled and shining.'
        q_flag_set 'oiled'
        return 0
      }
      q_say 'oil: what should I oil? Try:  oil gears'
      return 1
    }
    'clock' {
      if (($argv.Count -eq 2) -and ($argv[0] -eq '--wind') -and ($argv[1] -eq '--twice')) {
        q_ran_mark 'clock'
        q_say 'Tick, tock. Tick, tock. The clock is wound for the day.'
        q_flag_set 'wound'
        return 0
      }
      if (($argv.Count -eq 1) -and ($argv[0] -eq '--secret')) {
        q_ran_mark 'clock'
        q_say 'A little drawer springs open in the clock face. Inside, rolled up: a blueprint. You put it on the bench as blueprint.txt.'
        q_write 'blueprint.txt' 'BLUEPRINT: the Clockwork Owl. Ada''s next invention.
        A clock that hoots on the hour.
        '
        return 0
      }
      if (($argv.Count -eq 1) -and ($argv[0] -eq '--wind')) {
        q_ran_mark 'clock'
        q_say 'Tick, tock. That''s one wind. It needs two: --wind --twice.'
        return 0
      }
      q_say 'The clock wants options. Read it first: Get-Content clock.ps1'
      return 1
    }
    'gearbox' {
      if ((q_variable 'GEAR_SIZE' '7')) {
        q_ran_mark 'gearbox'
        q_say 'Clunk. Whirr. The gearbox turns, smooth as silk.'
        q_flag_set 'geared'
        return 0
      }
      q_say 'The gearbox grinds and stops: $GEAR_SIZE is not set. (Load the settings into this session: . .\settings.ps1)'
      return 1
    }
    'bell' {
      if (($argv.Count -eq 1) -and ($argv[0] -eq '--three-times') -and (q_flag 'geared')) {
        q_ran_mark 'bell'
        q_say 'DONG. DONG. DONG. The bell rings out over the town, and on the third ring something small and shiny falls from the tower and rolls to your feet.'
        q_flag_set 'rung'
        q_flag_set 'lucky'
        return 0
      }
      if ((q_flag 'geared')) {
        q_ran_mark 'bell'
        q_say 'DONG. The bell rings out over the whole town. Noon, right on time.'
        q_flag_set 'rung'
        return 0
      }
      q_say 'The bell rope hangs slack: the gearbox isn''t turning, so nothing pulls it.'
      return 1
    }
  }
  return 1
}
